<?php
if(file_exists(__DIR__.'/config.php')){header('Location: index.php');exit;}
$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{$host=trim($_POST['db_host']);$name=trim($_POST['db_name']);$user=trim($_POST['db_user']);$pass=$_POST['db_pass'];$pdo=new PDO("mysql:host=$host;dbname=$name;charset=utf8mb4",$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$sql=file_get_contents(__DIR__.'/app/schema.sql');foreach(array_filter(array_map('trim',explode(';',$sql))) as $query)$pdo->exec($query.';');$base=rtrim(dirname($_SERVER['SCRIPT_NAME']),'/\\');$cfg=['db_host'=>$host,'db_name'=>$name,'db_user'=>$user,'db_pass'=>$pass,'base_url'=>$base==='/'?'':$base];file_put_contents(__DIR__.'/config.php',"<?php\nreturn ".var_export($cfg,true).";\n");require __DIR__.'/app/core.php';save_setting('site_name',trim($_POST['site_name']));save_setting('logo',trim($_POST['logo']));save_setting('default_language','ru');save_setting('languages','{"ru":"Русский","en":"English"}');save_setting('blog_excerpt_length','180');save_setting('footer_text','© '.date('Y').' '.trim($_POST['site_name']));$pdo->prepare('INSERT INTO users(name,email,password,role,created_at) VALUES(?,?,?,?,?)')->execute([$_POST['admin_name'],$_POST['admin_email'],password_hash($_POST['admin_password'],PASSWORD_DEFAULT),'admin',date('Y-m-d H:i:s')]);$pdo->prepare('INSERT INTO content(type,status,title,slug,body,language,translation_group,author_id,created_at,updated_at) VALUES("page","published",?,?,?,?,?,?,?)')->execute(['Главная','home','<h2>Сайт готов к работе</h2><p>Отредактируйте эту страницу в панели управления.</p>','ru',bin2hex(random_bytes(12)),1,date('Y-m-d H:i:s'),date('Y-m-d H:i:s')]);header('Location: index.php?installed=1');exit;}catch(Throwable $e){$error=$e->getMessage();}}
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/style.css"><title>Установка SiteForge</title></head><body><main class="container install"><h1>Установка SiteForge</h1><p>Введите данные уже созданной базы MySQL и настройте первый сайт.</p><?php if($error):?><p class="error"><?=htmlspecialchars($error)?></p><?php endif;?><form method="post" class="card form-grid"><h2>База данных</h2><input name="db_host" value="localhost" placeholder="Хост БД" required><input name="db_name" placeholder="Имя БД" required><input name="db_user" placeholder="Пользователь БД" required><input name="db_pass" type="password" placeholder="Пароль БД"><h2>Сайт</h2><input name="site_name" placeholder="Название сайта" required><input name="logo" placeholder="URL логотипа (необязательно)"><h2>Администратор</h2><input name="admin_name" placeholder="Имя" required><input name="admin_email" type="email" placeholder="Email" required><input name="admin_password" type="password" minlength="8" placeholder="Пароль (мин. 8 символов)" required><button>Установить систему</button></form></main></body></html>
